<?php require '../includes/bootstrap.php';student_required();$rows=$pdo->query("SELECT p.*,e.event_name,e.status event_status FROM problem_statements p JOIN events e ON e.event_id=p.event_id WHERE e.status IN ('OPEN','UPCOMING') ORDER BY e.start_date,p.problem_code")->fetchAll();$cur=$pdo->prepare("SELECT problem_id FROM selections WHERE student_id=? AND status!='CANCELLED'");$cur->execute([$_SESSION['student_id']]);$current=(int)$cur->fetchColumn();$title='Problem Statements';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="team.php">Team</a><a href="history.php">History</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>Problem Statements</h1><p class="muted">Search challenges by title, domain, technology or event.</p><div class="filters"><input id="searchProblems" placeholder="Search problems..."><select onchange="location='?domain='+encodeURIComponent(this.value)"><option value="">All domains</option><?php foreach(array_unique(array_column($rows,'domain')) as $d):?><option><?=e($d)?></option><?php endforeach;?></select></div><div class="grid"><?php foreach($rows as $p):$count=selected_count($pdo,$p['problem_id']);$full=$count >= (int)$p['max_teams'];?><div class="card problem-card"><div class="row"><span class="badge"><?=e($p['difficulty'])?></span><span class="badge"><?=e($p['domain'])?></span></div><h3><?=e($p['problem_code'])?> · <?=e($p['title'])?></h3><p class="muted"><?=e($p['event_name'])?></p><p><?=e($p['description'])?></p><p class="muted">Technology: <?=e($p['technology']?:'Open')?> · Capacity: <?=$count?>/<?=e($p['max_teams'])?></p><?php if($current===$p['problem_id']):?><span class="badge">CURRENT SELECTION</span><?php elseif(!$full && $p['status']==='AVAILABLE' && $p['event_status']==='OPEN'):?><form method="post" action="../actions/select-problem.php"><input type="hidden" name="problem_id" value="<?=e($p['problem_id'])?>"><button class="btn"><?=$current?'Change to this':'Select Problem'?></button></form><?php else:?><span class="badge">Unavailable</span><?php endif;?></div><?php endforeach;?></div><?php include '../includes/footer.php';?>
